package com.secure.documentwallet;

import android.app.*;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.io.*;import java.util.concurrent.*;

/** Exports a short-lived cleartext copy; it deliberately does not claim to control the recipient. */
public class SecureShareHubActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private LinearLayout list;
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}LinearLayout page=VaultPageUi.page(this);page.addView(VaultPageUi.header(this,"Export A Document","Create a temporary PDF copy"));page.addView(VaultPageUi.notice(this,"share","Recipient Control Ends After Export","The receiving app can save its own copy. My Vault removes its temporary export after about 15 minutes.",0xfffff3dc,0xffb76a07));page.addView(VaultPageUi.sectionHead(this,"Choose A Document","PDF export"));list=Ui.column(this);page.addView(list);setContentView(VaultPageUi.screen(this,page,"profile"));load();}
 private void load(){io.execute(()->{try{JSONArray docs=new VaultRepository(this).all();runOnUiThread(()->render(docs));}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could Not Open Document Export"));}});}
 private void render(JSONArray docs){list.removeAllViews();if(docs.length()==0){list.addView(VaultPageUi.notice(this,"□","No Documents Yet","Scan or upload an item before exporting",Ui.SOFT,Ui.TEAL));return;}for(int i=docs.length()-1;i>=0;i--){JSONObject doc=docs.optJSONObject(i);if(doc==null)continue;LinearLayout row=VaultPageUi.iconRow(this,"share",doc.optString("title","Document"),doc.optString("category","Document")+" · Export a temporary PDF");row.setOnClickListener(v->confirm(doc));VaultPageUi.addRow(list,row);}}
 private void confirm(JSONObject doc){new AlertDialog.Builder(this).setTitle("Export "+doc.optString("title","Document")+"?").setMessage("My Vault will decrypt a temporary PDF, open Android's share panel, and schedule its own copy for cleanup. A recipient may keep any file you send.").setNegativeButton("Cancel",null).setPositiveButton("Prepare PDF",(d,w)->share(doc)).show();}
 private void share(JSONObject doc){ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage("Preparing Temporary PDF…");wait.show();io.execute(()->{try{DocumentExporter exporter=new DocumentExporter(this);File file=exporter.pdf(doc,doc.optJSONArray("pages")!=null&&doc.optJSONArray("pages").length()==2);runOnUiThread(()->{wait.dismiss();VaultActivityLog.add(this,"Document Exported",doc.optString("title","Document"));exporter.share(file,"application/pdf");});}catch(Exception e){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could Not Prepare This Document");});}});}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
